def get_destination_insights(slug):
    clean_slug = str(slug or '').lower().strip()
    if clean_slug in DESTINATION_INSIGHTS:
        return DESTINATION_INSIGHTS[clean_slug]
    name = clean_slug.replace('-', ' ').replace('_', ' ').title() if clean_slug else 'Destination'
    return {'name': name, 'state': 'India', 'slug': clean_slug, 'hidden_spots': [{'name': f'Old {name} Heritage Alley & Secret Viewpoint', 'badge': 'Secret Viewpoint', 'icon': '', 'description': f'A peaceful, lesser-traveled viewpoint tucked away in the old quarters of {name} offering breathtaking panoramas.', 'best_time': '07:00 AM – 09:00 AM (Serene morning light)', 'local_tip': 'Ask local vendors for the old stone staircase path that bypasses tourist traffic.'}, {'name': f'{name} Lakeside Pine Trail / Hidden Garden', 'badge': 'Nature Escape', 'icon': '', 'description': f'Tranquil walking pathway surrounded by native flora, peaceful chirping birds, and tranquil waters.', 'best_time': '04:30 PM – 06:30 PM (Golden sunset hours)', 'local_tip': 'Ideal for peaceful evening walks and stunning nature photography.'}], 'famous_food': [{'dish': f'Authentic {name} Regional Thali & Bread', 'diet_type': 'veg', 'icon': '', 'description': f'Wholesome assortment of local seasonal vegetables, slow-cooked dal, handmade flatbreads, and regional chutneys.', 'famous_spot': f'Heritage Old Town Market in {name}', 'price_est': '₹150 – ₹300 per thali', 'foodie_tip': 'Always ask for local homemade pickles and fresh buttermilk to accompany your meal.'}, {'dish': f'Traditional Spiced Sweets & Fresh Kulhad Chai', 'diet_type': 'veg', 'icon': '', 'description': f'Rich heritage sweet prepared with pure ghee and local dry fruits, served with steaming ginger-cardamom tea.', 'famous_spot': f'Main Bazaar Sweets Center, {name}', 'price_est': '₹40 – ₹100', 'foodie_tip': 'Enjoy hot chai in earthen clay cups for the rich mineral aroma.'}]}

def get_all_destination_insights(selected_slugs):
    if not selected_slugs:
        return [get_destination_insights('jaipur')]
    seen = set()
    res = []
    for s in selected_slugs:
        slug_clean = str(s).lower().strip()
        if slug_clean and slug_clean not in seen:
            seen.add(slug_clean)
            res.append(get_destination_insights(slug_clean))
    return res
